#pragma once
// Palette entries for the physics-world nodes (docs/plans/wave11/WORLD_STATE_DEBUG.md section 2.12; family version 1). NOT
// standalone: GraphNodeFamilies.gen.inc (generated by cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside
// namespace aver::editor::detail, after pin()/attr() are defined, and calls appendPhysicsWorldNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphPhysicsWorldNodeTable.cs pin for pin. A snapshot is the integer the Snapshot node
// puts on its pin (0 = failed); the graph may hold 16 at once and they die with the physics world. Stepping from a graph is not
// offered (it breaks the tick contract), nor are the profiler, the debug draw or the world origin.

inline void appendPhysicsWorldNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_PhysicsSetSetting", "Physics Set Setting", "Physics", {
        pin("exec", "exec", false), pin("value", "float", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("setting", "Setting (velocitySteps, positionSteps, collisionSteps, sleepTime, allowSleeping, deterministic, ...)")}});
    t.push_back({"AN_PhysicsGetSetting", "Physics Get Setting", "Physics", {
        pin("found", "bool", true), pin("value", "float", true)},
        {attr("setting", "Setting (velocitySteps, positionSteps, collisionSteps, sleepTime, allowSleeping, deterministic, ...)")}});
    t.push_back({"AN_PhysicsSnapshot", "Physics Snapshot", "Physics", {
        pin("exec", "exec", false), pin("then", "exec", true), pin("snapshot", "int", true), pin("success", "bool", true)},
        {attr("parts", "Parts (all, or any of bodies, contacts, constraints, characters, engine, statics)")}});
    t.push_back({"AN_PhysicsRestore", "Physics Restore", "Physics", {
        pin("exec", "exec", false), pin("snapshot", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_PhysicsReleaseSnapshot", "Physics Release Snapshot", "Physics", {
        pin("exec", "exec", false), pin("snapshot", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_PhysicsStateHash", "Physics State Hash", "Physics", {
        pin("low", "int", true), pin("high", "int", true)}});
    t.push_back({"AN_PhysicsStats", "Physics Stats", "Physics", {
        pin("bodies", "int", true), pin("activeDynamic", "int", true), pin("steps", "int", true),
        pin("stepMs", "float", true), pin("updateErrors", "int", true)}});
}
